B.ans=new A.S('Serbian Cyrillic (azbuka) has 30 letters, and each one is always read the same way: "write as you speak" (Vuk Karad\u017ei\u0107). The Latin alphabet (abeceda) is used alongside it \u2014 the same 30 sounds.',null)
B.aqp=new A.S('There are no iotated vowel letters (as in Russian: "yo", "yu", "ya") and no hard or soft signs. "\u0415" is always a plain "e" as in "bed" and never softens the consonant before it; the "y" sound is written \u0458, and the soft sounds are separate letters.',"\u043d\u0435 [ne], \u0458\u0430 (I), \u0459\u0443\u0431\u0430\u0432 (love), \u043a\u043e\u045a (horse)")
B.aOh=s([B.ans,B.aqp],t.R)
B.aw0=new A.aD("30 letters: one letter \u2014 one sound",B.aOh)
B.aqj=new A.S('\u045b \u2014 a soft "ch", close to "t" + "y" said together; \u0447 \u2014 a hard "ch" as in "church"; \u0452 \u2014 a soft "dj", like the "d" in "during" said quickly; \u045f \u2014 a hard "j" as in "jam"; \u0459 \u2014 "ly" as in "million"; \u045a \u2014 "ny" as in "canyon"; \u0458 \u2014 "y" as in "yes".',null)
B.are=new A.S("R can act as the vowel of a syllable \u2014 a syllable and the stress can rest on it.",null)
B.aKo=s([B.aqj,B.are],t.R)
B.ax6=new A.aD("Letters that look or sound unfamiliar",B.aKo)
B.apb=new A.S("Letter pairs worth memorising (Cyrillic = Latin): \u0447 = \u010d, \u045b = \u0107, \u0452 = \u0111, \u0436 = \u017e, \u0448 = \u0161, \u045f = d\u017e, \u0459 = lj, \u045a = nj, \u0458 = j, \u0446 = c, \u0445 = h.",null)
B.aZ8=s([B.apb],t.R)
